@Tags(['golden'])
library;

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:zaghlol/features/accounts/presentation/card_detail/card_detail.dart';
import 'package:zaghlol/features/accounts/presentation/card_detail/card_detail_providers.dart';
import 'package:zaghlol/features/accounts/presentation/card_detail/compare.dart';
import 'package:zaghlol/features/insights/domain/chart_models.dart';

import '../../../support/golden_matrix.dart';
import 'card_detail_test.dart' as base;

// Goldens are generated by CI (`--update-goldens`); PNGs are not committed.
void main() {
  for (final v in goldenVariants) {
    testWidgets('card detail golden ${v.name}', (t) async {
      await t.binding.setSurfaceSize(const Size(390, 1500));
      addTearDown(() => t.binding.setSurfaceSize(null));
      await t.pumpWidget(
        base.host(
          const CardDetailScreen(accountId: 'a1'),
          overrides: base.detailOverrides(),
          locale: v.locale,
          dark: v.dark,
        ),
      );
      await t.pumpAndSettle();
      await expectLater(
        find.byType(MaterialApp),
        matchesGoldenFile('../../../goldens/card_detail_${v.name}.png'),
      );
    });

    testWidgets('compare cards golden ${v.name}', (t) async {
      await t.binding.setSurfaceSize(const Size(390, 700));
      addTearDown(() => t.binding.setSurfaceSize(null));
      final cards = [
        CompareCard(
          accountId: 'a1',
          label: 'NBE',
          spend: base.m(891000),
          byCategory: {'dining': base.m(210000), 'groc': base.m(300000)},
        ),
        CompareCard(
          accountId: 'a2',
          label: 'CIB',
          spend: base.m(495000),
          byCategory: {'dining': base.m(175000), 'groc': base.m(140000)},
        ),
      ];
      await t.pumpWidget(
        base.host(
          const CompareCardsScreen(),
          overrides: [
            compareDataProvider.overrideWith(
              (ref) async => CompareData(
                currencies: [base.egp],
                currency: base.egp,
                available: cards,
                cards: cards,
                categoryIds: const ['groc', 'dining'],
                period: ChartPeriod.month(2026, 11),
              ),
            ),
          ],
          locale: v.locale,
          dark: v.dark,
        ),
      );
      await t.pumpAndSettle();
      await expectLater(
        find.byType(MaterialApp),
        matchesGoldenFile('../../../goldens/compare_cards_${v.name}.png'),
      );
    });
  }
}
